    console.log("");
}
async function promptId(message, registry, current) {
    const { value } = await prompts({
        type: "text",
        name: "value",
        message,
        initial: current,
        validate: (input) => {
            const id = input.trim();
            if (id.length === 0)
                return "ID is required";
            if (!ID_RE.test(id))
                return "Use lowercase letters, numbers, '-' and '_' only";
            if (id !== current && registry.providers[id])
                return `Provider "${id}" already exists`;
            return true;
        },
    });
    return value ? String(value).trim() : undefined;
}
async function addProvider() {
    const registry = await readRegistry();
