    if (doCheck) {
        console.log(c.dim(`\n  Checking ${baseURL} …`));
        const result = await healthCheck(baseURL, apiKey);
        if (result.ok) {
            console.log(c.green(`  OK — ${result.modelCount} model(s) found.`) + c.dim(`  (${result.baseURL})`));
