        case "list":
            return listProviders();
        case "add":
            return addProvider();
        case "edit":
            return withProvider("Select a provider to edit", editProvider);
        case "toggle":
            return withProvider("Select a provider to toggle", toggleProvider);
        case "test":
            return withProvider("Select a provider to test", testProvider);
